"""Save-file version migration chain.

Schema history:
  v1: {"version": 1, "name": str, "hp": int, "items": [str]}
  v2: {"version": 2, "name": str, "health": int, "level": 1, "items": [str]}
      - renamed hp -> health, added level (default 1)
  v3: {"version": 3, "name": str, "health": int, "level": int,
       "weapons": [str], "consumables": [str]}
      - split items by rule: names containing "sword" or "bow" are weapons,
        everything else consumable
"""

from __future__ import annotations

LATEST_VERSION = 3

WEAPON_KEYWORDS = ("sword", "bow")


def _migrate_v1_to_v2(save: dict) -> dict:
    """v1 -> v2: rename hp to health, add level defaulting to 1."""
    out = dict(save)
    if save["version"] != 1:
        raise ValueError(f"v1->v2 migration got version {save['version']}")
    out.pop("version", None)
    out["version"] = 2
    if "hp" in out:
        out["health"] = out.pop("hp")
    out.setdefault("level", 1)
    return out


def _is_weapon(item: str) -> bool:
    lowered = item.lower()
    return any(kw in lowered for kw in WEAPON_KEYWORDS)


def _migrate_v2_to_v3(save: dict) -> dict:
    """v2 -> v3: split items into weapons and consumables."""
    if save["version"] != 2:
        raise ValueError(f"v2->v3 migration got version {save['version']}")
    out = dict(save)
    items = out.pop("items", [])
    weapons: list[str] = []
    consumables: list[str] = []
    for item in items:
        (weapons if _is_weapon(item) else consumables).append(item)
    out["weapons"] = weapons
    out["consumables"] = consumables
    out["version"] = 3
    return out


# Ordered chain of single-step migrations.
MIGRATIONS = {
    1: _migrate_v1_to_v2,
    2: _migrate_v2_to_v3,
}


def migrate(save: dict) -> dict:
    """Bring a save dict up to the latest version via the migration chain."""
    if not isinstance(save, dict):
        raise TypeError("save must be a dict")
    version = save.get("version")
    if not isinstance(version, int):
        raise ValueError("save is missing an integer 'version' field")
    if version > LATEST_VERSION:
        raise ValueError(
            f"unknown save version {version} (latest supported: {LATEST_VERSION})"
        )
    current = dict(save)
    while current["version"] < LATEST_VERSION:
        step = MIGRATIONS.get(current["version"])
        if step is None:
            raise ValueError(f"no migration from version {current['version']}")
        current = step(current)
    return current


def load(save: dict) -> dict:
    """Migrate (if needed) and validate the final v3 shape."""
    migrated = migrate(save)
    required = {"version", "name", "health", "level", "weapons", "consumables"}
    missing = required - migrated.keys()
    if missing:
        raise ValueError(f"invalid save, missing fields: {sorted(missing)}")
    if migrated["version"] != LATEST_VERSION:
        raise ValueError(f"expected version {LATEST_VERSION}")
    if not isinstance(migrated["name"], str):
        raise ValueError("'name' must be a string")
    for key in ("health", "level"):
        if not isinstance(migrated[key], int) or isinstance(migrated[key], bool):
            raise ValueError(f"'{key}' must be an int")
    for key in ("weapons", "consumables"):
        if not isinstance(migrated[key], list) or not all(
            isinstance(i, str) for i in migrated[key]
        ):
            raise ValueError(f"'{key}' must be a list of strings")
    return migrated

