import pytest

from save_migration import migrate, load


@pytest.fixture
def v1_save():
    return {"version": 1, "name": "Aria", "hp": 100, "items": ["iron sword", "health potion", "short bow"]}


@pytest.fixture
def v2_save():
    return {"version": 2, "name": "Aria", "health": 100, "level": 1, "items": ["iron sword", "health potion", "short bow"]}


@pytest.fixture
def v3_save():
    return {
        "version": 3,
        "name": "Aria",
        "health": 100,
        "level": 1,
        "weapons": ["iron sword", "short bow"],
        "consumables": ["health potion"],
    }


EXPECTED_V3 = {
    "version": 3,
    "name": "Aria",
    "health": 100,
    "level": 1,
    "weapons": ["iron sword", "short bow"],
    "consumables": ["health potion"],
}


class TestMigrationChain:
    def test_v1_migrates_to_expected_v3(self, v1_save):
        assert migrate(v1_save) == EXPECTED_V3

    def test_v2_migrates_to_expected_v3(self, v2_save):
        assert migrate(v2_save) == EXPECTED_V3

    def test_v3_is_unchanged(self, v3_save):
        assert migrate(v3_save) == EXPECTED_V3

    def test_load_validates_final_shape(self, v1_save, v2_save, v3_save):
        for save in (v1_save, v2_save, v3_save):
            assert load(save) == EXPECTED_V3

    def test_unknown_future_version_raises(self):
        with pytest.raises(ValueError, match="unknown save version"):
            migrate({"version": 99, "name": "X"})

    def test_idempotent_on_v3(self, v3_save):
        once = migrate(v3_save)
        twice = migrate(once)
        assert once == twice == v3_save

    def test_input_not_mutated(self, v1_save):
        original = dict(v1_save)
        migrate(v1_save)
        assert v1_save == original

    def test_v1_default_level_applied(self):
        result = migrate({"version": 1, "name": "Bob", "hp": 5, "items": []})
        assert result["level"] == 1
        assert result["health"] == 5

    def test_case_insensitive_weapon_rule(self):
        result = migrate({"version": 2, "name": "C", "health": 1, "level": 2, "items": ["CrossBOW", "bread"]})
        assert result["weapons"] == ["CrossBOW"]
        assert result["consumables"] == ["bread"]

    def test_load_rejects_bad_shape(self, v3_save):
        bad = dict(v3_save)
        del bad["weapons"]
        with pytest.raises(ValueError, match="missing fields"):
            load(bad)

